double limitM = Tama.Args.Get(args, "limitMetres", 1000.0);
string filter = Tama.Args.Get(args, "titleContains", "");
var outList = new List<object>();
foreach (Document d in app.Documents)
{
    if (d.IsFamilyDocument) continue;
    if (filter.Length > 0 && !d.Title.Contains(filter)) continue;
    var far = new List<object>();
    double maxR = 0;
    int n = 0;
    foreach (Element e in new FilteredElementCollector(d).WhereElementIsNotElementType())
    {
        BoundingBoxXYZ bb = null;
        try { bb = e.get_BoundingBox(null); } catch {}
        if (bb == null) continue;
        n++;
        var c = (bb.Min + bb.Max) / 2;
        double r = Math.Sqrt(c.X*c.X + c.Y*c.Y) * 0.3048;
        if (r > maxR) maxR = r;
        if (r > limitM && far.Count < 15)
            far.Add(new { id = e.Id.IntegerValue, cat = e.Category?.Name, name = e.Name,
                centre_m = new[]{Math.Round(c.X*0.3048,1), Math.Round(c.Y*0.3048,1)}, dist_km = Math.Round(r/1000,2) });
    }
    outList.Add(new { title = d.Title, isLinked = d.IsLinked, elementsWithBox = n, maxDistFromOrigin_m = Math.Round(maxR,1), farElements = far });
}
return outList;
